const Pset = P.P;
const Tset = P.T;
const a = 1.36;
const b = 0.0318;
const R = 0.08206;
v.fn(x => 1, { color: H.colors.grid, width: 1.5, dash: [6, 5] });
const Zfn = (Pr, Tk) => {
  let Vm = R * Tk / Pr + b;
  for (let i = 0; i < 40; i++) {
    const denom = Pr + a / (Vm * Vm);
    if (denom <= 0) break;
    Vm = R * Tk / denom + b;
  }
  return Pr * Vm / (R * Tk);
};
